import type { ComponentProps } from "react";
import StackIcon from "tech-stack-icons";
import { SiArgo, SiJenkins } from "react-icons/si";

export type IconProps = ComponentProps<"svg">;

type TechIconProps = {
    className?: string;
};

/**
 * Tech Stack Icons
 *
 * Light/dark variants are handled with Tailwind:
 * - light variant → shown in light mode
 * - dark variant  → shown in dark mode
 *
 * Light and dark variants are selected with CSS so this registry remains
 * safe to use from Server Components.
 */
function TechIcon({
    name,
    className,
}: {
    name: Parameters<typeof StackIcon>[0]["name"];
    className?: string;
}) {
    return (
        <>
            {/* {" "}
            {theme === "dark" ? (
                <StackIcon name={name} variant="dark" className={className} />
            ) : (
                <StackIcon name={name} variant="light" className={className} />
            )} */}
            <span className="inline-flex">
                <span className="dark:hidden">
                    <StackIcon
                        name={name}
                        variant="light"
                        className={className}
                    />
                </span>

                <span className="hidden dark:inline-flex">
                    <StackIcon
                        name={name}
                        variant="dark"
                        className={className}
                    />
                </span>
            </span>
        </>
    );
}

function SimpleIcon({
    icon: Icon,
    className,
}: {
    icon: React.ComponentType<IconProps>;
    className?: string;
}) {
    return <Icon className={className} aria-hidden />;
}

